components.css:
  .ds-image-fan { display: block; }
  .ds-fan-stage {
    --card-width: clamp(92px, 25vw, 176px);
    --rest-spread: .72;
    --active-spread: .88;
    --spread: calc(var(--card-width) * var(--rest-spread));
    position: relative;
    height: calc(var(--card-width) * 1.5 + 80px);
    margin-top: var(--space-6, 24px);
  }
  .ds-fan-card {
    position: absolute;
    top: 32px;
    left: 50%;
    z-index: var(--layer);
    width: var(--card-width);
    padding: 8px 8px 12px;
    border-radius: 12px;
    background: var(--paper, #faf9f6);
    color: var(--ink, #2b2d28);
    box-shadow: 0 8px 24px rgb(43 45 40 / .12);
    text-decoration: none;
    text-align: center;
    transform-origin: center 75%;
    transform: translateX(calc(-50% + var(--position) * var(--spread))) translateY(var(--drop)) rotate(var(--angle));
    transition: transform 400ms var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1)), box-shadow 400ms var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1));
  }
  .ds-fan-card img { display: block; width: 100%; height: auto; aspect-ratio: 3 / 4; object-fit: cover; border-radius: 4px; }
  .ds-fan-card span { display: block; margin-top: 8px; font-size: 12px; line-height: 1.5; }
  .ds-fan-stage:has(.ds-fan-card:is(:hover, :focus-visible)) { --spread: calc(var(--card-width) * var(--active-spread)); }
  .ds-fan-card:is(:hover, :focus-visible) {
    z-index: 3;
    color: var(--ink, #2b2d28);
    transform: translateX(calc(-50% + var(--position) * var(--spread))) translateY(-16px) rotate(0deg);
    box-shadow: 0 16px 32px rgb(43 45 40 / .16);
  }
  .ds-fan-card:focus-visible { outline: 2px solid var(--accent, #526640); outline-offset: 5px; }
  .ds-fan-hint { color: var(--muted, #72736a); font-size: var(--text-caption, 13px); text-align: center; margin-bottom: 0; }
  .ds-has-entered .ds-fan-card { animation: fan-unfold 650ms var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1)) backwards; animation-delay: calc(var(--order) * 70ms); }
  @keyframes fan-unfold {
    from { transform: translateX(-50%) translateY(20px) rotate(0deg); }
  }
.ds-fan-card svg{display:block;width:100%;height:auto;aspect-ratio:3/4;border-radius:4px}.ds-image-fan{font-family:DM Sans Variable,sans-serif}@media(max-width:600px){.ds-fan-stage{--card-width:clamp(82px,25vw,112px);--rest-spread:1.12;--active-spread:1.12}}@media(prefers-reduced-motion:reduce){.ds-fan-card{animation:none!important;transition:none!important}.ds-fan-stage:has(.ds-fan-card:is(:hover,:focus-visible)){--spread:calc(var(--card-width)*var(--rest-spread))}.ds-fan-card:is(:hover,:focus-visible){transform:translateX(calc(-50% + var(--position)*var(--spread))) translateY(var(--drop)) rotate(var(--angle))}}
